presetParts.perFrame:
st = max (0, st-0.2/fps);
dec = 1-0.5/fps;
st_ = st_* (dec) + (1-dec)*st;

//dir
dir = 0.7*sin(time*.0162+rany*6);
q2 = dir+0.5; 
q3 = sin(dir);
q4 = cos(dir);

//scaling plane
q7 = 0.002;

//movement
posx = time*0.0003;
posy = time*0.004;
q10 = posx;
q11 = posy;

//start ran for warp mod 
q15 = ranx;
q16 = rany;

