float comb (float2 uvi) {return dot (tex2D(sampler_noise_lq, uvi).yx, float2(1,1));}

float2 noise2 (float2 uvi) {float2 tmp = 1; float s = 1;
  for (int n = 1; n <= 2; n +=1 ) {tmp *= 1-tex2D(sampler_noise_lq,uvi*s); s*= 3;}
  return tmp;}


float2 noise3 (float3 uvi, float3 mod) {uvi *= 0.16; float2 tmp = 1; float s = 1; float diff = 0;
  uvi.xy+= modran*3;
  for (int n = 1; n <= 2; n +=1 ) {tmp *= sat(1-tex2D(sampler_noise_lq,uvi*s)*(0.8+mod.y/2)/s); s*= 3+tmp*0.002*mod.z;}
  for (int n = 1; n <= 3; n +=1 ) {tmp *= sat(1-tex2D(sampler_noise_lq,uvi*s)*(0.8+mod.y/2)/s); s*= 3;}
  diff = sat (16-2*uvi.z-20000* abs (tmp.x-0.4)) ;
  tmp  -= diff*0.009 ;
  return 1-pow (tmp,0.8+mod.x);}

float2 enoise3 (float2 uvi, float3 mod) {uvi/=6; float2 tmp = 1; float s = 1;
  for (int n = 1; n <= 6; n +=1 ) {tmp *= 1-tex2D(sampler_noise_lq,uvi*s)/(0.8+mod.y)/s; s*= 2.9;}
  if ((tmp.x > 0.398) && (tmp.x < 0.402)) {tmp = 0.398;}
  return 1-pow (tmp,.8+2*mod.x);}

float3 rs_lav (float2 uvi, float berg) {  float z; float2 rs;
  z = 1/(uvi.y+hory)*(alti-berg*16); //z = clamp(z,0,4/xyscale);
